// ═══ NEW FEATURES TO ADOPT ═══

// RECORDS (Java 14) — replace POJO boilerplate:
// Before: class Trade { private String id; private BigDecimal amount; /* getters, equals, hashCode, toString */ }
record Trade(String id, BigDecimal amount) {}  // one line!

// TEXT BLOCKS (Java 15):
String sql = """
    SELECT t.trade_id, t.amount
    FROM trades t
    WHERE t.status = 'SETTLED'
    ORDER BY t.amount DESC
    """;

// PATTERN MATCHING instanceof (Java 16):
// Before: if (obj instanceof Trade) { Trade t = (Trade) obj; use(t); }
if (obj instanceof Trade t) { use(t); }  // cast + bind in one step!

// SEALED CLASSES (Java 17):
sealed interface PaymentChannel permits NEFT, UPI, RTGS {}
record NEFT() implements PaymentChannel {}
record UPI() implements PaymentChannel {}
record RTGS() implements PaymentChannel {}

// SWITCH EXPRESSIONS (Java 14):
String label = switch (channel) {
    case NEFT n -> "National Electronic Fund Transfer";
    case UPI u -> "Unified Payments Interface";
    case RTGS r -> "Real-Time Gross Settlement";
};
