package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class Java8To17Test {

    // A migration readiness check for one concern.
    String migrationAction(String issue) {
        return switch (issue) {                       // Java 17 switch expression
            case "removed-module"   -> "add explicit dependency";
            case "internal-access"  -> "use supported API or --add-opens";
            case "old-library"      -> "bump to Java 17-compatible version";
            default                 -> "no action";
        };
    }

    @Test
    void mapsIssuesToActions() {
        assertThat(migrationAction("removed-module")).isEqualTo("add explicit dependency");
        assertThat(migrationAction("internal-access")).isEqualTo("use supported API or --add-opens");
        assertThat(migrationAction("old-library")).contains("bump");
    }
}
